  ('FIS-0075', 'Física', 'Mecánica - leyes de Newton (F=ma)', 2, null, null, 'Si una fuerza de 60 N produce una aceleración de 4 m/s² en un objeto, ¿cuál es su masa?', '{"A":"14.0 kg","B":"15.0 kg","C":"16.0 kg","D":"240 kg"}'::jsonb, 'B', 'Despejando de F = m×a: m = F/a = 60/4 = 15.0 kg.'),
  ('FIS-0076', 'Física', 'Mecánica - leyes de Newton (F=ma)', 2, null, null, 'Si una fuerza de 50 N produce una aceleración de 2 m/s² en un objeto, ¿cuál es su masa?', '{"A":"25.0 kg","B":"26.0 kg","C":"100 kg","D":"24.0 kg"}'::jsonb, 'A', 'Despejando de F = m×a: m = F/a = 50/2 = 25.0 kg.'),
