  ('FIS-0172', 'Física', 'Electricidad - conceptos generales', 1, null, null, '¿Qué fenómeno describe la atracción o repulsión entre cargas eléctricas?', '{"A":"La ley de Coulomb","B":"La ley de Ohm","C":"La ley de la gravitación universal","D":"La primera ley de Newton"}'::jsonb, 'A', 'Este es un concepto fundamental de electricidad estudiado a nivel secundaria/bachillerato.'),
  ('FIS-0173', 'Física', 'Electricidad - conceptos generales', 1, null, null, '¿Qué es un circuito en serie?', '{"A":"Un circuito donde los componentes están conectados uno después de otro, formando un solo camino para la corriente","B":"Un tipo de imán permanente","C":"Un circuito que no permite el paso de corriente","D":"Un circuito donde cada componente tiene su propio camino independiente"}'::jsonb, 'A', 'Este es un concepto fundamental de electricidad estudiado a nivel secundaria/bachillerato.'),
  ('FIS-0174', 'Física', 'Electricidad - conceptos generales', 1, null, null, '¿Qué es un circuito en paralelo?', '{"A":"Un dispositivo para medir voltaje","B":"Un circuito sin resistencia","C":"Un circuito donde los componentes están conectados en ramas separadas, cada una con su propio camino para la corriente","D":"Un circuito con un solo camino para toda la corriente"}'::jsonb, 'C', 'Este es un concepto fundamental de electricidad estudiado a nivel secundaria/bachillerato.'),
