  ('GEO-0081', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué nombre reciben las formaciones montañosas producidas por el choque de placas tectónicas?', '{"A":"Cordilleras (u orogenias)","B":"Llanuras","C":"Deltas","D":"Mesetas exclusivamente sin relación tectónica"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0082', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es una meseta, en términos de relieve?', '{"A":"Una isla volcánica","B":"Un tipo de río subterráneo","C":"Una extensión de terreno plano y elevado respecto al nivel del mar","D":"Una depresión profunda bajo el nivel del mar"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0083', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es una llanura?', '{"A":"Una extensión de terreno plano, generalmente a poca altitud sobre el nivel del mar","B":"Un tipo de arrecife de coral","C":"Un cráter volcánico","D":"Una montaña de gran altitud"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0084', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es un delta, en geografía fluvial?', '{"A":"La formación de tierra en la desembocadura de un río, por acumulación de sedimentos","B":"Un tipo de lago artificial","C":"El nacimiento de un río en la montaña","D":"Una cordillera submarina"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
