  ('GEO-0087', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es el Círculo Polar Ártico?', '{"A":"Una zona desértica del hemisferio norte","B":"Una cordillera montañosa en el polo norte","C":"Un tipo de corriente marina fría","D":"Una línea imaginaria que delimita la región donde ocurre el fenómeno del sol de medianoche"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0088', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Cuál es el continente más extenso del mundo?', '{"A":"América","B":"Asia","C":"África","D":"Europa"}'::jsonb, 'B', 'Concepto fundamental de geografía física.'),
  ('GEO-0089', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Cuál es el continente más pequeño del mundo (excluyendo la Antártida)?', '{"A":"Europa","B":"África","C":"América del Sur","D":"Oceanía"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0090', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Cuál es el océano más pequeño del mundo?', '{"A":"El océano Ártico","B":"El océano Índico","C":"El océano Pacífico","D":"El océano Atlántico"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0091', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es una corriente marina?', '{"A":"Un tipo de ola producida por terremotos","B":"Un fenómeno exclusivo de los ríos","C":"Un flujo continuo y dirigido de agua oceánica, que puede ser cálida o fría","D":"Una línea imaginaria de longitud"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0092', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué corriente marina cálida influye en el clima templado de Europa occidental?', '{"A":"La corriente de Kuroshio","B":"La corriente de Humboldt","C":"La corriente del Golfo","D":"La corriente de California"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0093', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es un volcán?', '{"A":"Una depresión producida por la erosión eólica","B":"Una montaña formada exclusivamente por sedimentos marinos","C":"Un tipo de glaciar en zonas polares","D":"Una abertura en la corteza terrestre por donde emerge material fundido del interior de la Tierra"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0094', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué fenómeno geológico se produce por el choque o fricción entre placas tectónicas y libera energía en forma de ondas sísmicas?', '{"A":"Una sequía","B":"Un huracán","C":"Un tsunami exclusivamente sin relación sísmica","D":"Un terremoto (sismo)"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0095', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es un glaciar?', '{"A":"Un volcán inactivo cubierto de nieve","B":"Una corriente marina polar","C":"Una gran masa de hielo formada por la acumulación y compactación de nieve a lo largo del tiempo","D":"Un tipo de desierto frío sin hielo"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0096', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es la erosión, en geografía física?', '{"A":"La formación de nuevas montañas por actividad volcánica","B":"El proceso de evaporación del agua de los océanos","C":"El desgaste y transporte de materiales de la superficie terrestre por agentes como el agua, el viento o el hielo","D":"El movimiento de las placas tectónicas"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0097', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es una isla?', '{"A":"Una porción de tierra rodeada completamente de agua","B":"Un tipo de arrecife artificial","C":"Una montaña submarina que no llega a la superficie","D":"Una península unida al continente por un istmo"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0098', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es una península?', '{"A":"Una isla completamente rodeada de agua","B":"Una porción de tierra rodeada de agua por casi todos sus lados, excepto por una franja que la conecta con el continente","C":"Una cordillera submarina","D":"Un tipo de bahía profunda"}'::jsonb, 'B', 'Concepto fundamental de geografía física.'),
  ('GEO-0099', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es un istmo?', '{"A":"Un tipo de desierto costero","B":"Una cadena montañosa submarina","C":"Una isla aislada en medio del océano","D":"Una franja estrecha de tierra que conecta dos masas continentales más grandes"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0100', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es un estrecho, en geografía?', '{"A":"Una montaña con forma alargada","B":"Un paso de mar angosto que conecta dos grandes masas de agua","C":"Una franja de tierra que une dos continentes","D":"Un tipo de bahía poco profunda"}'::jsonb, 'B', 'Concepto fundamental de geografía física.'),
  ('GEO-0101', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué zona climática se caracteriza por temperaturas extremadamente bajas todo el año, cerca de los polos?', '{"A":"Clima mediterráneo","B":"Clima desértico cálido","C":"Clima tropical","D":"Clima polar"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0102', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué zona climática se caracteriza por veranos e inviernos marcados, con estaciones bien diferenciadas, típica del interior de los continentes?', '{"A":"Clima polar","B":"Clima continental","C":"Clima ecuatorial","D":"Clima tropical húmedo"}'::jsonb, 'B', 'Concepto fundamental de geografía física.'),
  ('GEO-0103', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es la altitud y cómo afecta al clima de una región?', '{"A":"La cantidad de lluvia anual de una región","B":"La distancia de una región al ecuador exclusivamente","C":"La altura sobre el nivel del mar; a mayor altitud, generalmente menor temperatura","D":"El tipo de suelo predominante en la región"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0104', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es la latitud y cómo afecta al clima?', '{"A":"La distancia de un lugar al mar más cercano","B":"La distancia angular de un punto respecto al ecuador; a mayor latitud, generalmente menor temperatura","C":"El tipo de vegetación de una región","D":"La altura de un lugar sobre el nivel del mar"}'::jsonb, 'B', 'Concepto fundamental de geografía física.'),
  ('GEO-0105', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué son los trópicos de Cáncer y Capricornio?', '{"A":"Cordilleras ubicadas en el hemisferio sur","B":"Corrientes marinas cálidas del Pacífico","C":"Paralelos que delimitan la zona donde el sol puede estar directamente sobre la vertical (zona intertropical)","D":"Meridianos que dividen los husos horarios"}'::jsonb, 'C', 'Concepto fundamental de geografía física.'),
  ('GEO-0106', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué característica define a un bosque templado?', '{"A":"Presenta estaciones bien marcadas y árboles como robles y pinos, en zonas de clima templado","B":"Ausencia total de vegetación por el frío extremo","C":"Vegetación exclusivamente de cactáceas","D":"Temperaturas altas constantes y lluvias todo el año"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0107', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué característica define a la sabana como tipo de vegetación?', '{"A":"Pastizales con árboles dispersos, típica de climas tropicales con estación seca marcada","B":"Ausencia total de vegetación por aridez extrema","C":"Vegetación de coníferas en climas fríos","D":"Bosques densos con lluvia constante todo el año"}'::jsonb, 'A', 'Concepto fundamental de geografía física.'),
  ('GEO-0108', 'Geografía', 'Relieve, ríos y climas del mundo', 2, null, null, '¿Qué es la selva tropical (bosque lluvioso)?', '{"A":"Una zona sin biodiversidad significativa","B":"Un ecosistema árido con escasa vegetación","C":"Un tipo de bosque exclusivo de climas fríos","D":"Un ecosistema con abundante vegetación y biodiversidad, propio de climas cálidos y húmedos"}'::jsonb, 'D', 'Concepto fundamental de geografía física.'),
  ('GEO-0109', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la densidad de población?', '{"A":"La tasa de natalidad de una región","B":"El número total de habitantes de un país","C":"El porcentaje de población urbana","D":"El número de habitantes por unidad de superficie (por ejemplo, por km²)"}'::jsonb, 'D', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0110', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Cuál es el país más poblado del mundo actualmente (según estimaciones recientes)?', '{"A":"India","B":"China","C":"Estados Unidos","D":"Indonesia"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0111', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la migración, en términos demográficos?', '{"A":"La distribución de recursos naturales","B":"El crecimiento natural de una población","C":"El desplazamiento de personas de un lugar a otro, cambiando su lugar de residencia","D":"Un tipo de clima estacional"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0112', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por urbanización?', '{"A":"El proceso de crecimiento de las ciudades y aumento de la población que vive en zonas urbanas","B":"La construcción exclusiva de zonas industriales","C":"La disminución de la población mundial","D":"El abandono total de las zonas rurales"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0113', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la tasa de natalidad?', '{"A":"El número de nacimientos por cada mil habitantes en un periodo determinado","B":"La cantidad de matrimonios registrados al año","C":"El porcentaje de personas mayores de 65 años","D":"El número de personas que emigran de un país"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0114', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la tasa de mortalidad?', '{"A":"El número de defunciones por cada mil habitantes en un periodo determinado","B":"El porcentaje de población que emigra","C":"El crecimiento económico de un país","D":"El número de nacimientos en un año"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0115', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es una megalópolis?', '{"A":"Un tipo de clima urbano","B":"Un pequeño poblado rural","C":"Una extensa área urbana formada por la unión de varias ciudades y sus zonas metropolitanas","D":"Una zona exclusivamente industrial sin población"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0116', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué factores suelen influir en la distribución de la población mundial?', '{"A":"Únicamente el color del suelo","B":"Exclusivamente la cercanía a volcanes activos","C":"El clima, el relieve, la disponibilidad de agua y las actividades económicas","D":"Solo la temperatura promedio anual"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0117', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es una pirámide de población?', '{"A":"Un indicador exclusivo de la actividad económica","B":"Una gráfica que representa la distribución de una población por edad y sexo","C":"Un tipo de monumento arqueológico","D":"Una medida de la superficie de un país"}'::jsonb, 'B', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0118', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por esperanza de vida?', '{"A":"La edad mínima legal para trabajar","B":"El promedio de años que se espera que viva una persona en una población determinada","C":"El número total de habitantes de un país","D":"El porcentaje de población que vive en ciudades"}'::jsonb, 'B', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0119', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la emigración?', '{"A":"La construcción de nuevas ciudades","B":"El crecimiento natural de la población","C":"La salida de personas de su país o región de origen hacia otro lugar","D":"La llegada de personas a un país distinto al de origen"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0120', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la inmigración?', '{"A":"El aumento de la tasa de natalidad","B":"La salida de personas de su país de origen","C":"La disminución de la población urbana","D":"La llegada de personas a un país o región distinto al de su origen para establecerse ahí"}'::jsonb, 'D', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0121', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es una zona metropolitana?', '{"A":"Una región exclusivamente rural sin ciudades","B":"Un país completo sin divisiones internas","C":"El área que incluye una ciudad central y los municipios o localidades conurbadas que dependen económicamente de ella","D":"Un tipo de clima urbano específico"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0122', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por población económicamente activa (PEA)?', '{"A":"El conjunto de personas en edad de trabajar que están empleadas o buscan empleo activamente","B":"Únicamente los estudiantes universitarios","C":"Solo las personas jubiladas","D":"Todos los habitantes de un país sin excepción"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0123', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es el envejecimiento poblacional?', '{"A":"La disminución de la esperanza de vida","B":"El crecimiento acelerado de las zonas rurales","C":"El aumento en la tasa de natalidad de un país","D":"El aumento en la proporción de personas de edad avanzada dentro de una población"}'::jsonb, 'D', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0124', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la transición demográfica?', '{"A":"La urbanización exclusiva de zonas costeras","B":"El proceso histórico de cambio de altas tasas de natalidad y mortalidad a tasas bajas, conforme un país se desarrolla","C":"Un tipo de migración forzada por conflictos","D":"El cambio climático en una región determinada"}'::jsonb, 'B', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0125', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué características suele tener una pirámide de población de un país en desarrollo, con alta natalidad?', '{"A":"Una base angosta y una cúspide ancha","B":"Una forma completamente rectangular","C":"Una forma invertida con más ancianos que jóvenes","D":"Una base ancha, reflejando una gran proporción de población joven"}'::jsonb, 'D', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0126', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por ''población rural''?', '{"A":"La población que vive exclusivamente en grandes ciudades","B":"La población que trabaja únicamente en el sector servicios","C":"La población que habita en localidades pequeñas, generalmente dedicada a actividades agropecuarias","D":"La totalidad de la población de un país"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0127', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por ''población urbana''?', '{"A":"La población que vive exclusivamente en el campo","B":"La población dedicada únicamente a la agricultura","C":"La población que habita en ciudades y zonas con alta concentración de habitantes e infraestructura","D":"La población menor de edad de un país"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0128', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué factor demográfico mide el número de hijos promedio que tendría una mujer durante su vida fértil?', '{"A":"La esperanza de vida","B":"La tasa de urbanización","C":"La tasa de mortalidad infantil","D":"La tasa de fecundidad"}'::jsonb, 'D', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0129', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es un flujo migratorio?', '{"A":"El movimiento de un grupo de personas desde un lugar de origen hacia un lugar de destino en un periodo determinado","B":"Una medida de la densidad de población","C":"Un tipo de corriente marina","D":"Un fenómeno climático estacional"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0130', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la segregación urbana?', '{"A":"La separación espacial de grupos sociales dentro de una ciudad, generalmente por nivel socioeconómico","B":"El crecimiento poblacional de una zona rural","C":"Un tipo de clima urbano","D":"La construcción de nuevas carreteras en una ciudad"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0131', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué papel juegan las remesas en la economía de países con alta emigración, como México?', '{"A":"Representan un ingreso económico importante enviado por migrantes a sus familias en el país de origen","B":"Son subsidios que el gobierno da a los migrantes para salir del país","C":"Son impuestos que los migrantes pagan a su país de destino","D":"No tienen ningún impacto económico relevante"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0132', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es una favela o asentamiento irregular en el contexto urbano latinoamericano?', '{"A":"Áreas naturales protegidas dentro de las ciudades","B":"Barrios residenciales de altos ingresos","C":"Zonas de vivienda precaria, generalmente surgidas de forma no planificada en las periferias urbanas","D":"Zonas industriales exclusivamente"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0133', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es la conurbación?', '{"A":"El abandono total de una zona urbana","B":"La separación de una ciudad en varios municipios independientes","C":"El proceso de unión física entre dos o más ciudades que originalmente estaban separadas, formando una sola área urbana continua","D":"Un tipo de clima característico de las grandes ciudades"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0134', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué indicador se usa comúnmente para medir el nivel de desarrollo humano de un país, combinando salud, educación e ingreso?', '{"A":"La tasa de natalidad exclusivamente","B":"El número total de habitantes","C":"El Índice de Desarrollo Humano (IDH)","D":"La superficie territorial del país"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0135', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué se entiende por ''brecha digital'' en geografía humana?', '{"A":"La distancia física entre dos ciudades","B":"Un tipo de frontera política","C":"La desigualdad en el acceso a tecnologías de información entre distintas regiones o grupos sociales","D":"La diferencia de husos horarios entre países"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0136', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué región del mundo tiene actualmente una de las tasas de natalidad más altas?', '{"A":"Asia oriental","B":"Europa occidental","C":"África subsahariana","D":"América del Norte"}'::jsonb, 'C', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0137', 'Geografía', 'Población y geografía humana', 2, null, null, '¿Qué es un país ''sobrepoblado'' en términos relativos?', '{"A":"Un país donde la población excede la capacidad de sus recursos y infraestructura disponibles","B":"Un país con superficie territorial muy extensa","C":"Un país con baja densidad de población","D":"Un país con alta esperanza de vida"}'::jsonb, 'A', 'Concepto fundamental de geografía humana y demografía.'),
  ('GEO-0138', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es un recurso natural renovable?', '{"A":"Un recurso que se agota y no puede regenerarse, como el petróleo","B":"Un recurso fabricado exclusivamente por el ser humano","C":"Un tipo de moneda internacional","D":"Un recurso que se regenera de forma natural en un periodo razonable, como el agua o los bosques"}'::jsonb, 'D', 'Concepto fundamental de geografía económica.'),
  ('GEO-0139', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es un recurso natural no renovable?', '{"A":"Un recurso que no se regenera o tarda millones de años en formarse, como el petróleo o el carbón","B":"Un recurso que se regenera rápidamente, como el viento","C":"Un producto manufacturado en fábricas","D":"Un recurso disponible de forma ilimitada"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0140', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué actividad económica se dedica a la extracción directa de recursos naturales, como la agricultura, ganadería, pesca y minería?', '{"A":"El sector primario","B":"El sector terciario","C":"El sector cuaternario","D":"El sector secundario"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0141', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué actividad económica transforma las materias primas en productos manufacturados?', '{"A":"El sector informal exclusivamente","B":"El sector primario","C":"El sector terciario","D":"El sector secundario (industria)"}'::jsonb, 'D', 'Concepto fundamental de geografía económica.'),
  ('GEO-0142', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué actividad económica incluye los servicios, como el comercio, la educación y el turismo?', '{"A":"El sector extractivo","B":"El sector secundario","C":"El sector terciario","D":"El sector primario"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0143', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué son las energías renovables?', '{"A":"Un tipo de energía que se agota en pocos años","B":"Energía generada únicamente por centrales nucleares","C":"Fuentes de energía basadas exclusivamente en combustibles fósiles","D":"Fuentes de energía que provienen de recursos naturales inagotables, como el sol, el viento y el agua"}'::jsonb, 'D', 'Concepto fundamental de geografía económica.'),
  ('GEO-0144', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué región del mundo es conocida por concentrar las mayores reservas de petróleo?', '{"A":"Medio Oriente","B":"Oceanía","C":"Antártida","D":"Europa del Norte"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0145', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es la globalización, en el contexto de la geografía económica?', '{"A":"El proceso de creciente interconexión económica, cultural y política entre países del mundo","B":"Un tipo de clima que afecta solo a zonas tropicales","C":"El aislamiento comercial de un país respecto al resto del mundo","D":"Una política exclusiva de países en desarrollo"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0146', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es el sector cuaternario de la economía?', '{"A":"El sector dedicado exclusivamente a la agricultura","B":"El sector dedicado únicamente a la construcción","C":"El sector encargado de la extracción de minerales","D":"El sector relacionado con actividades intelectuales y de información, como investigación y desarrollo tecnológico"}'::jsonb, 'D', 'Concepto fundamental de geografía económica.'),
  ('GEO-0147', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es un tratado de libre comercio?', '{"A":"Un tipo de moneda compartida entre países","B":"Un impuesto adicional sobre las importaciones","C":"Un acuerdo entre países para reducir o eliminar barreras arancelarias al comercio entre ellos","D":"Una prohibición total de comercio entre naciones"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0148', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué producto agrícola es uno de los principales cultivos de exportación de países como Colombia y Brasil?', '{"A":"El café","B":"El algodón exclusivamente","C":"La soya exclusivamente","D":"El trigo"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0149', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué región del mundo concentra gran parte de la manufactura electrónica global actualmente?', '{"A":"África subsahariana","B":"Oceanía","C":"Asia oriental (China, Corea del Sur, Taiwán, entre otros)","D":"América del Sur"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0150', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es una zona económica especial?', '{"A":"Un área geográfica delimitada con reglas económicas distintas (como menores impuestos) para atraer inversión","B":"Un área exclusivamente turística sin comercio","C":"Una región protegida por su valor ecológico exclusivamente","D":"Una zona sin ninguna actividad económica permitida"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0151', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué recurso natural es fundamental en la matriz energética de países como Arabia Saudita y Venezuela?', '{"A":"El carbón exclusivamente","B":"El petróleo","C":"El gas natural exclusivamente sin petróleo","D":"La energía eólica"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0152', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es la balanza comercial de un país?', '{"A":"La diferencia entre el valor de sus exportaciones y sus importaciones","B":"El tipo de cambio de su moneda","C":"El total de impuestos recaudados en un año","D":"El número de empresas registradas en el país"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
  ('GEO-0153', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué se entiende por ''materia prima'' en economía?', '{"A":"Un servicio ofrecido al consumidor final","B":"Un producto ya terminado listo para la venta","C":"Un recurso natural utilizado como insumo básico en un proceso de producción","D":"Un tipo de moneda de intercambio internacional"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0154', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es el turismo como actividad económica?', '{"A":"Una actividad exclusiva del sector primario","B":"Un servicio del sector terciario relacionado con los viajes y la estancia de personas fuera de su lugar habitual","C":"Una actividad relacionada únicamente con la minería","D":"Un tipo de industria manufacturera"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0155', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué son los ''países emergentes'' en el contexto económico mundial?', '{"A":"Los países con las economías más desarrolladas del mundo","B":"Naciones en proceso de rápido crecimiento económico e industrialización, como Brasil, India o México","C":"Países que han dejado de participar en el comercio internacional","D":"Naciones sin ningún tipo de actividad económica"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0156', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es el comercio justo (fair trade)?', '{"A":"Un sistema que elimina cualquier tipo de comercio internacional","B":"Un modelo de comercio que busca condiciones más equitativas para productores, especialmente en países en desarrollo","C":"Un impuesto exclusivo sobre productos de lujo","D":"Una política que prohíbe la exportación de alimentos"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0157', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué región concentra la mayor producción mundial de cobre, incluyendo a Chile como principal productor?', '{"A":"Oceanía","B":"América del Sur","C":"Europa del Este","D":"América del Norte"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0158', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es la agricultura de subsistencia?', '{"A":"Una agricultura orientada exclusivamente a la exportación masiva","B":"Un tipo de agricultura orientada a producir alimentos principalmente para el consumo de la propia familia o comunidad","C":"Un tipo de ganadería industrializada","D":"Una técnica de pesca en aguas profundas"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0159', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es la agroindustria?', '{"A":"Una rama de la minería subterránea","B":"Un sector relacionado únicamente con servicios financieros","C":"El conjunto de actividades económicas relacionadas con la transformación de productos agrícolas y ganaderos","D":"Un tipo de actividad exclusivamente extractiva sin transformación"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0160', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es una maquiladora, término usado frecuentemente en el contexto económico de México?', '{"A":"Un tipo de institución financiera","B":"Una tienda dedicada exclusivamente a la venta minorista","C":"Una granja dedicada a la agricultura orgánica","D":"Una planta industrial que ensambla o procesa productos, generalmente para exportación, usando insumos importados"}'::jsonb, 'D', 'Concepto fundamental de geografía económica.'),
  ('GEO-0161', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué organismo internacional regula y promueve el comercio entre países, estableciendo normas comerciales globales?', '{"A":"El Fondo Monetario Internacional (exclusivamente)","B":"La Organización Mundial del Comercio (OMC)","C":"La Organización Mundial de la Salud","D":"La Organización de las Naciones Unidas (exclusivamente en temas comerciales)"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0162', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué región es conocida como el ''granero del mundo'' por su alta producción de cereales, como trigo y maíz?', '{"A":"El desierto del Sahara","B":"La región de las llanuras de Estados Unidos, Canadá, Argentina y algunas zonas de Europa del Este","C":"El Ártico","D":"La región amazónica"}'::jsonb, 'B', 'Concepto fundamental de geografía económica.'),
  ('GEO-0163', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué es la pesca industrial, a diferencia de la pesca artesanal?', '{"A":"Una actividad prohibida en todos los países","B":"Una técnica de pesca practicada únicamente por comunidades pequeñas para consumo propio","C":"La captura de grandes volúmenes de peces mediante embarcaciones y tecnología a gran escala, orientada al mercado masivo","D":"Un tipo de agricultura marina exclusivamente orgánica"}'::jsonb, 'C', 'Concepto fundamental de geografía económica.'),
  ('GEO-0164', 'Geografía', 'Recursos naturales y actividades económicas', 2, null, null, '¿Qué región del mundo es reconocida por su alta producción de arroz, siendo esencial en su dieta y economía?', '{"A":"El sudeste asiático (incluyendo países como China, India, Tailandia y Vietnam)","B":"América Central exclusivamente","C":"El norte de África","D":"Escandinavia"}'::jsonb, 'A', 'Concepto fundamental de geografía económica.'),
