  ('GEO-0193', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es la escala de un mapa?', '{"A":"El número total de países representados","B":"El color utilizado para representar la altitud","C":"El tipo de proyección cartográfica utilizada exclusivamente","D":"La relación entre las distancias representadas en el mapa y las distancias reales en el terreno"}'::jsonb, 'D', 'Concepto fundamental de cartografía.'),
  ('GEO-0194', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es un huso horario?', '{"A":"Una zona de alta actividad sísmica","B":"Un tipo de proyección cartográfica","C":"Una línea que divide climas distintos","D":"Cada una de las 24 divisiones de la Tierra que comparten la misma hora, basadas en la longitud"}'::jsonb, 'D', 'Concepto fundamental de cartografía.'),
  ('GEO-0195', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es una proyección cartográfica?', '{"A":"Un sistema de coordenadas exclusivo para la navegación aérea","B":"Una medida de altitud sobre el nivel del mar","C":"Un tipo de brújula digital","D":"Un método para representar la superficie curva de la Tierra sobre una superficie plana, como un mapa"}'::jsonb, 'D', 'Concepto fundamental de cartografía.'),
  ('GEO-0196', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es un mapa topográfico?', '{"A":"Un mapa que muestra únicamente los límites políticos","B":"Un mapa usado solo para la navegación marítima","C":"Un mapa que representa exclusivamente el clima de una región","D":"Un mapa que representa las formas del relieve de un territorio mediante curvas de nivel"}'::jsonb, 'D', 'Concepto fundamental de cartografía.'),
  ('GEO-0197', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué son las curvas de nivel en un mapa topográfico?', '{"A":"Líneas que indican la densidad de población","B":"Líneas que representan las fronteras entre países","C":"Líneas que muestran las corrientes marinas","D":"Líneas que conectan puntos de igual altitud sobre el nivel del mar"}'::jsonb, 'D', 'Concepto fundamental de cartografía.'),
  ('GEO-0198', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es el GPS (Sistema de Posicionamiento Global)?', '{"A":"Un sistema de satélites que permite determinar la ubicación exacta de un punto en la superficie terrestre","B":"Un tipo de mapa impreso tradicional","C":"Un instrumento para medir la temperatura ambiental","D":"Una proyección cartográfica específica"}'::jsonb, 'A', 'Concepto fundamental de cartografía.'),
  ('GEO-0199', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es un mapa temático?', '{"A":"Un mapa diseñado para representar un tema específico, como el clima, la población o los recursos naturales de una región","B":"Un mapa sin ningún tipo de información adicional","C":"Un mapa exclusivo para la navegación aérea","D":"Un mapa que representa únicamente el relieve"}'::jsonb, 'A', 'Concepto fundamental de cartografía.'),
  ('GEO-0200', 'Geografía', 'Cartografía - conceptos y orientación', 2, null, null, '¿Qué es la teledetección (o percepción remota) en geografía?', '{"A":"Un método de medición de la profundidad oceánica con sonar","B":"La técnica de obtener información sobre la superficie terrestre a través de sensores en satélites o aviones, sin contacto directo","C":"El uso exclusivo de brújulas para orientarse","D":"Una técnica de dibujo manual de mapas"}'::jsonb, 'B', 'Concepto fundamental de cartografía.'),
