  ('HMX-0001', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué civilización mesoamericana es reconocida por su avanzado conocimiento de astronomía y su calendario, además de sus ciudades como Chichén Itzá y Palenque?', '{"A":"Los toltecas","B":"Los olmecas","C":"Los mexicas","D":"Los mayas"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0002', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué civilización es considerada la ''cultura madre'' de Mesoamérica, conocida por sus cabezas colosales de piedra?', '{"A":"Los olmecas","B":"Los zapotecas","C":"Los mexicas","D":"Los mayas"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0003', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Cuál era la capital del imperio mexica (azteca) al momento de la llegada de los españoles?', '{"A":"Teotihuacán","B":"Tenochtitlan","C":"Monte Albán","D":"Tula"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0004', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿En qué lago se fundó la ciudad de Tenochtitlan?', '{"A":"El lago de Chapala","B":"El lago de Pátzcuaro","C":"El lago de Texcoco","D":"El lago de Xochimilco exclusivamente"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0005', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué civilización construyó la gran ciudad de Teotihuacán, con sus pirámides del Sol y de la Luna?', '{"A":"Los mixtecos exclusivamente","B":"Una cultura cuyo origen étnico exacto aún se debate, conocida como los teotihuacanos","C":"Los mayas exclusivamente","D":"Los mexicas exclusivamente"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0006', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué dios mexica estaba asociado con la guerra y el sol?', '{"A":"Quetzalcóatl","B":"Huitzilopochtli","C":"Xochiquetzal","D":"Tláloc"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0007', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué dios era representado como una serpiente emplumada y era venerado por varias culturas mesoamericanas, incluidos toltecas y mexicas?', '{"A":"Quetzalcóatl","B":"Huitzilopochtli","C":"Tezcatlipoca","D":"Tláloc"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0008', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué sistema de escritura utilizaban los mayas?', '{"A":"El alfabeto latino","B":"Un sistema numérico exclusivamente sin escritura","C":"La escritura cuneiforme","D":"Un sistema de escritura jeroglífica"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0009', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué cultura desarrolló Monte Albán, un importante centro ceremonial en el actual estado de Oaxaca?', '{"A":"Los mayas","B":"Los mexicas","C":"Los zapotecas","D":"Los toltecas"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0010', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué producto agrícola fue la base de la alimentación en las civilizaciones mesoamericanas?', '{"A":"El trigo","B":"El arroz","C":"La papa exclusivamente","D":"El maíz"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0011', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué es la Triple Alianza en el contexto del imperio mexica?', '{"A":"Una alianza entre mayas, olmecas y zapotecas","B":"La alianza entre Tenochtitlan, Texcoco y Tlacopan que dominó gran parte de Mesoamérica","C":"Un tratado firmado con los conquistadores españoles","D":"Una confederación de pueblos del norte de México"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0012', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué sistema agrícola utilizaban los mexicas para cultivar en el lago de Texcoco?', '{"A":"Las chinampas","B":"El barbecho exclusivamente","C":"La agricultura de terrazas exclusivamente andina","D":"El riego por goteo"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0013', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué cultura precedió a los mexicas en el centro de México y es asociada con la ciudad de Tula?', '{"A":"Los purépechas","B":"Los mayas","C":"Los toltecas","D":"Los olmecas"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0014', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué pueblo mesoamericano resistió con éxito el dominio del imperio mexica, manteniéndose independiente en el occidente de México?', '{"A":"Los zapotecas","B":"Los totonacas","C":"Los huastecos","D":"Los purépechas (tarascos)"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0015', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué calendario utilizaban los mexicas para organizar el tiempo, además del calendario ritual de 260 días?', '{"A":"Un calendario lunar exclusivo de 12 meses","B":"El calendario solar de 365 días (Xiuhpohualli)","C":"El calendario gregoriano","D":"El calendario juliano"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0016', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué culturas antiguas del norte de México se caracterizaron por ser principalmente nómadas o seminómadas, a diferencia de las culturas mesoamericanas sedentarias?', '{"A":"Los zapotecas","B":"Los mayas","C":"Los pueblos chichimecas","D":"Los mexicas"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0017', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué juego ritual practicado por varias culturas mesoamericanas se jugaba en canchas especiales con una pelota de hule?', '{"A":"El patolli exclusivamente sin relación con pelota","B":"El tlachtli entendido como danza, no juego","C":"El juego de pelota (ulama)","D":"La lucha libre prehispánica"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0018', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué material usaban los mexicas y otras culturas mesoamericanas para fabricar herramientas cortantes y armas?', '{"A":"La obsidiana","B":"El acero","C":"El hierro","D":"El bronce"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0019', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué producto derivado del agave era una bebida ritual importante en la cultura mexica?', '{"A":"La cerveza","B":"El tequila (bebida destilada posterior a la Colonia)","C":"El vino de uva","D":"El pulque"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0020', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué emperador (tlatoani) mexica gobernaba Tenochtitlan al momento de la llegada de Hernán Cortés?', '{"A":"Itzcóatl","B":"Cuauhtémoc","C":"Netzahualcóyotl","D":"Moctezuma II (Moctezuma Xocoyotzin)"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0021', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué último tlatoani mexica resistió el asedio final de Tenochtitlan ante los españoles?', '{"A":"Cuauhtémoc","B":"Tízoc","C":"Moctezuma II","D":"Netzahualcóyotl"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0022', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué gobernante de Texcoco es célebre por ser también un destacado poeta y filósofo en la cultura náhuatl prehispánica?', '{"A":"Moctezuma II","B":"Netzahualcóyotl","C":"Itzcóatl","D":"Cuauhtémoc"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0023', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué tipo de organización social y política tenían las ciudades-estado mayas?', '{"A":"Una monarquía hereditaria unificada desde el inicio","B":"Una democracia directa con elecciones populares","C":"Ciudades-estado independientes, cada una gobernada por su propio gobernante (ajaw), sin una unidad política central","D":"Un imperio centralizado bajo un único emperador"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0024', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué tipo de estructura arquitectónica religiosa es característica de las civilizaciones mesoamericanas, usada para rituales y ceremonias?', '{"A":"Las mezquitas","B":"Los anfiteatros romanos","C":"Las pirámides (templos escalonados)","D":"Las catedrales góticas"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0025', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué sistema numérico, basado en puntos y barras, utilizaban los mayas, incluyendo el concepto del cero?', '{"A":"Un sistema vigesimal (base 20)","B":"Un sistema binario","C":"Un sistema decimal (base 10)","D":"Un sistema hexadecimal"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0026', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué actividad económica complementaba la agricultura entre los pueblos mesoamericanos costeros, como los mayas de la península de Yucatán?', '{"A":"La minería de hierro","B":"La industria textil mecanizada","C":"La pesca y el comercio marítimo","D":"La ganadería de bovinos (inexistente antes de la Colonia)"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0027', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué imperio mesoamericano tenía como práctica religiosa común los sacrificios humanos, asociados a la cosmovisión de mantener el orden cósmico?', '{"A":"Exclusivamente los zapotecas","B":"El imperio mexica, entre otras culturas mesoamericanas","C":"Únicamente los mayas","D":"Ninguna cultura mesoamericana practicó sacrificios"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0028', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué material se usaba comúnmente para construir las viviendas comunes del pueblo en la época prehispánica, a diferencia de los templos de piedra?', '{"A":"Ladrillo cocido industrial","B":"Concreto armado","C":"Adobe, madera y materiales perecederos como el zacate","D":"Vidrio y acero"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0029', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué código o documento pictográfico prehispánico o colonial temprano sirve como fuente histórica sobre la vida y cultura mexica?', '{"A":"Las actas notariales modernas","B":"Los tratados internacionales","C":"Los periódicos coloniales","D":"Los códices (como el Códice Mendoza o el Códice Florentino)"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0030', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué es el ''tributo'' en el contexto del imperio mexica?', '{"A":"Un tipo de moneda usada en el comercio mexica","B":"Un impuesto exclusivo sobre la tierra agrícola","C":"Una ofrenda voluntaria sin obligación","D":"Los bienes y productos que los pueblos sometidos debían entregar periódicamente a Tenochtitlan"}'::jsonb, 'D', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0031', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué región de Mesoamérica fue el centro principal de la civilización maya durante su periodo Clásico?', '{"A":"La costa del Pacífico exclusivamente","B":"La península de Yucatán, Guatemala, Belice y partes de Chiapas y Honduras","C":"El norte árido de México","D":"El altiplano central de México exclusivamente"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0032', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué mercado (tianguis) mesoamericano fue descrito por los cronistas españoles como uno de los más grandes e importantes de su época, ubicado cerca de Tenochtitlan?', '{"A":"El mercado de Teotihuacán","B":"El mercado de Palenque","C":"El mercado de Tlatelolco","D":"El mercado de Monte Albán"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0033', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué tipo de gobierno tenía el imperio mexica en su cúspide, encabezado por el tlatoani?', '{"A":"Una monarquía con fuerte componente teocrático y militar","B":"Una democracia representativa","C":"Un gobierno colegiado sin líder único","D":"Una república federal"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0034', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué región de Mesoamérica es asociada principalmente con la cultura huasteca?', '{"A":"La selva Lacandona exclusivamente","B":"El altiplano de Oaxaca","C":"La zona costera del Golfo de México, entre los actuales estados de Veracruz, Tamaulipas, San Luis Potosí e Hidalgo","D":"La península de Baja California"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0035', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué instrumento se usaba en la vida cotidiana mesoamericana para moler el maíz y preparar la masa para tortillas?', '{"A":"El molino de viento","B":"El metate y el metlapil (mano de moler)","C":"La licuadora eléctrica","D":"El molino de agua europeo"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0036', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué actividad artesanal destacaba entre los pueblos mixtecos, reconocidos por sus finos trabajos en metales preciosos como el oro?', '{"A":"La orfebrería","B":"La fabricación de armas de fuego","C":"La producción de vidrio soplado","D":"La construcción naval"}'::jsonb, 'A', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0037', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué se entiende por ''cosmovisión'' en el contexto de las culturas prehispánicas?', '{"A":"Un tipo de mapa geográfico prehispánico","B":"Un calendario exclusivo para fines agrícolas","C":"La forma particular en que un pueblo concibe y explica el universo, la naturaleza y su lugar en el mundo","D":"Un sistema de escritura jeroglífica exclusivamente"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0038', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué papel jugaban los sacerdotes en la sociedad mexica?', '{"A":"Eran considerados esclavos dentro de la sociedad","B":"Dirigían los rituales religiosos, interpretaban los calendarios y tenían gran influencia social y política","C":"Se dedicaban exclusivamente al comercio","D":"No tenían ninguna relevancia social"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0039', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué grupo social mexica tenía la función principal de comerciar a larga distancia y también servía como informantes militares?', '{"A":"Los pipiltin exclusivamente sin relación comercial","B":"Los pochtecas","C":"Los macehuales","D":"Los tlatoque"}'::jsonb, 'B', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0040', 'Historia', 'México: Mesoamérica y civilizaciones prehispánicas', 2, null, null, '¿Qué grupo social conformaba la base de la sociedad mexica, dedicado principalmente a la agricultura y oficios comunes?', '{"A":"Los sacerdotes","B":"Los pipiltin (nobleza)","C":"Los macehualtin (macehuales)","D":"Los pochtecas"}'::jsonb, 'C', 'Concepto fundamental de la historia prehispánica de México.'),
  ('HMX-0041', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿En qué año llegó Hernán Cortés a las costas de lo que hoy es México?', '{"A":"1531","B":"1519","C":"1521","D":"1492"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0042', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿En qué año cayó Tenochtitlan ante los españoles, marcando el fin del imperio mexica?', '{"A":"1492","B":"1810","C":"1521","D":"1519"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0043', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Quién fue la mujer indígena que sirvió como intérprete y consejera de Hernán Cortés durante la conquista?', '{"A":"Isabel Moctezuma","B":"La Malinche (Malintzin)","C":"Josefa Ortiz de Domínguez","D":"Sor Juana Inés de la Cruz"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0044', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Cómo se llamó el sistema colonial que otorgaba a los españoles el derecho a recibir tributo y trabajo de los indígenas?', '{"A":"La encomienda","B":"El cabildo","C":"La audiencia","D":"El virreinato"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0045', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Cómo se llamó el territorio colonial español que abarcaba gran parte de México y Centroamérica durante la época colonial?', '{"A":"El Reino de la Nueva Galicia exclusivamente","B":"El Virreinato del Perú","C":"La Capitanía General de Guatemala exclusivamente","D":"El Virreinato de la Nueva España"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0046', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué institución de la Iglesia católica tuvo como función perseguir la herejía durante la época colonial?', '{"A":"La Real Audiencia","B":"El Consulado","C":"La Inquisición","D":"El Cabildo"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0047', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué metal precioso fue uno de los principales recursos extraídos por los españoles durante la Colonia, especialmente en Zacatecas y Guanajuato?', '{"A":"El cobre","B":"El hierro","C":"El oro exclusivamente","D":"La plata"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0048', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué se entiende por ''castas'' en la sociedad novohispana?', '{"A":"Un sistema de clasificación social basado en la mezcla de orígenes étnicos (español, indígena y africano)","B":"Un sistema exclusivamente religioso","C":"Una división territorial administrativa","D":"Un tipo de moneda utilizada en la Colonia"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0049', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué destacada escritora y poetisa novohispana es reconocida como una de las figuras intelectuales más importantes de la época colonial?', '{"A":"Leona Vicario","B":"Sor Juana Inés de la Cruz","C":"Josefa Ortiz de Domínguez","D":"La Malinche"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0050', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué evento marcó el primer gran contacto entre los pueblos indígenas de Mesoamérica y los europeos, antes de la caída de Tenochtitlan?', '{"A":"La firma de la independencia en 1821","B":"La fundación de Tenochtitlan","C":"La llegada de los primeros misioneros franciscanos en 1600","D":"La llegada de Hernán Cortés a Veracruz en 1519"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0051', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué institución administraba la justicia en nombre del rey en la Nueva España?', '{"A":"La Real Audiencia","B":"El Consejo de Trento","C":"La Casa de Contratación exclusivamente","D":"El Cabildo exclusivamente"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0052', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué máximo cargo político representaba al rey de España en el gobierno de la Nueva España?', '{"A":"El virrey","B":"El alcalde mayor","C":"El obispo","D":"El gobernador exclusivamente"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0053', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué papel jugaron las órdenes religiosas (franciscanos, dominicos, agustinos) durante la Colonia?', '{"A":"Gobernaron políticamente el virreinato en lugar del virrey","B":"No tuvieron ninguna participación relevante en la Colonia","C":"Evangelizaron a la población indígena y fundaron misiones, escuelas y hospitales","D":"Se dedicaron exclusivamente al comercio marítimo"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0054', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué es el mestizaje, proceso central en la formación de la sociedad mexicana durante la Colonia?', '{"A":"Un tipo de organización política colonial","B":"La mezcla biológica y cultural entre españoles, indígenas y, en menor medida, africanos","C":"La migración exclusiva de españoles a América","D":"La separación estricta entre las distintas razas sin mezcla alguna"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0055', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué producto llegó a América gracias al comercio colonial y se convirtió en un cultivo importante en Nueva España, aunque no era originario de allí?', '{"A":"El jitomate","B":"El cacao","C":"El maíz","D":"La caña de azúcar"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0056', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué ruta comercial marítima conectaba a la Nueva España (vía Acapulco) con Asia (Filipinas) durante la Colonia?', '{"A":"El Camino Real de Tierra Adentro exclusivamente","B":"La Ruta de la Seda terrestre","C":"La ruta del Atlántico Norte","D":"La Nao de China (Galeón de Manila)"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0057', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué camino colonial conectaba la Ciudad de México con las minas del norte, como Zacatecas?', '{"A":"El Camino de Santiago","B":"La Nao de China","C":"El Camino Real de Tierra Adentro","D":"La Ruta Panamericana"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0058', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué institución económica regulaba el comercio entre España y sus colonias americanas durante gran parte de la Colonia?', '{"A":"El Consulado de Comerciantes exclusivamente","B":"El Banco de México","C":"La Real Audiencia","D":"La Casa de Contratación de Sevilla"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0059', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué grupo de la sociedad colonial estaba formado por personas nacidas en América de padres españoles?', '{"A":"Los peninsulares","B":"Los indígenas","C":"Los mestizos","D":"Los criollos"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0060', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué grupo de la sociedad colonial gozaba de mayores privilegios políticos por haber nacido en España?', '{"A":"Los mestizos","B":"Los criollos","C":"Los indígenas","D":"Los peninsulares (gachupines)"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0061', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué población fue traída forzosamente de África a la Nueva España, principalmente para trabajar en labores agrícolas y mineras?', '{"A":"Mercenarios de origen árabe","B":"Trabajadores contratados de Asia","C":"Personas esclavizadas de origen africano","D":"Colonos voluntarios de Europa del Norte"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0062', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué construcción arquitectónica religiosa es característica del arte colonial en México, combinando elementos europeos e indígenas?', '{"A":"El estilo gótico puro sin influencia local","B":"El estilo neoclásico exclusivamente","C":"El barroco novohispano (como en catedrales y templos)","D":"El estilo modernista del siglo XX"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0063', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué universidad, una de las primeras de América, fue fundada en la Ciudad de México durante la Colonia (1551)?', '{"A":"El Colegio de San Ildefonso exclusivamente","B":"La UNAM en su forma moderna","C":"La Real y Pontificia Universidad de México","D":"El Instituto Politécnico Nacional"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0064', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué idioma se convirtió en la lengua oficial y dominante durante la Colonia, aunque persistieron muchas lenguas indígenas?', '{"A":"El español","B":"El latín exclusivamente","C":"El náhuatl exclusivamente","D":"El portugués"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0065', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué reformas administrativas del siglo XVIII buscaron modernizar y centralizar el control español sobre sus colonias, incluida la Nueva España?', '{"A":"Las Leyes de Indias del siglo XVI","B":"Las Leyes de Reforma del siglo XIX","C":"Las Reformas Borbónicas","D":"La Constitución de Cádiz de 1812"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0066', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué evento de 1808 en España (invasión napoleónica) debilitó la autoridad real y contribuyó indirectamente al surgimiento de movimientos independentistas en América?', '{"A":"La firma del Tratado de Tordesillas","B":"La fundación de la Casa de Contratación","C":"El descubrimiento de América","D":"La invasión napoleónica a España y la abdicación forzada del rey Fernando VII"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0067', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué grupo indígena del norte de la Nueva España mantuvo una fuerte resistencia contra el dominio colonial español durante gran parte de la época virreinal?', '{"A":"Los mexicas tras la conquista","B":"Los mayas de Yucatán exclusivamente","C":"Los apaches y otros pueblos del norte (como los chichimecas en periodos anteriores)","D":"Los zapotecas de Oaxaca"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0068', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué institución eclesiástica se encargaba de recolectar el diezmo, un impuesto religioso sobre la producción agrícola en la Nueva España?', '{"A":"La Iglesia católica, a través del sistema de diezmos","B":"La Real Hacienda exclusivamente","C":"El Cabildo municipal","D":"La Casa de Moneda"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0069', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué institución acuñaba las monedas de la Nueva España durante la Colonia?', '{"A":"El Consulado de Comerciantes","B":"El Banco de España","C":"La Casa de Contratación","D":"La Casa de Moneda de México"}'::jsonb, 'D', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0070', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué fenómeno demográfico ocurrió entre la población indígena en las primeras décadas tras la conquista, principalmente por enfermedades traídas de Europa?', '{"A":"Una migración masiva hacia Europa","B":"Una drástica disminución poblacional debido a epidemias como la viruela","C":"Ningún cambio demográfico significativo","D":"Un rápido crecimiento poblacional sin precedentes"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0071', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué cultivo de origen americano se exportó a Europa durante la Colonia y transformó la dieta y economía del Viejo Mundo?', '{"A":"El cacao (entre otros como el maíz, la papa y el jitomate)","B":"El trigo","C":"El arroz","D":"La caña de azúcar"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0072', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué papel cumplían los cabildos (ayuntamientos) en las ciudades de la Nueva España?', '{"A":"Comandar las fuerzas militares virreinales","B":"Administrar exclusivamente asuntos religiosos","C":"Administrar los asuntos locales y de gobierno municipal","D":"Gobernar todo el virreinato en lugar del virrey"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0073', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿En qué siglo se estableció formalmente el Virreinato de la Nueva España, tras la caída de Tenochtitlan?', '{"A":"El siglo XVIII exclusivamente","B":"El siglo XV","C":"El siglo XVI (a partir de 1535, con el primer virrey Antonio de Mendoza)","D":"El siglo XVII"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0074', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Quién fue el primer virrey de la Nueva España?', '{"A":"Antonio de Mendoza","B":"Hernán Cortés","C":"Martín de Mayorga","D":"Luis de Velasco"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0075', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué tipo de arte y arquitectura floreció especialmente en ciudades mineras como Guanajuato y Zacatecas durante la Colonia, gracias a la riqueza de la plata?', '{"A":"El arte moderno abstracto","B":"El arte prehispánico sin influencia europea","C":"El barroco (incluyendo el estilo churrigueresco)","D":"El estilo art déco"}'::jsonb, 'C', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0076', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué conflicto ocurrió en 1692 en la Ciudad de México, relacionado con el descontento popular por la escasez de maíz?', '{"A":"El motín de 1692 (Tumulto de 1692)","B":"El levantamiento de Tupac Amaru","C":"La Guerra de Reforma","D":"La Guerra de los Pasteles"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0077', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué grupo étnico del sureste de la Nueva España, particularmente en Yucatán, mantuvo su cultura e idioma de forma notable durante toda la Colonia?', '{"A":"Los mayas yucatecos","B":"Los apaches","C":"Los tarahumaras exclusivamente","D":"Los seris exclusivamente"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0078', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Cómo se le llamaba a los territorios del norte de la Nueva España, poco poblados y con presencia de misiones, como la Alta California y Texas?', '{"A":"Las provincias internas","B":"La Intendencia de México","C":"El Reino de Nueva Galicia exclusivamente","D":"El Bajío"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0079', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué figura eclesiástica, Bartolomé de las Casas, es reconocida históricamente por su defensa de los derechos de los pueblos indígenas ante los abusos coloniales?', '{"A":"Fray Bernardino de Sahagún exclusivamente por otra razón (cronista)","B":"Fray Bartolomé de las Casas","C":"El virrey Antonio de Mendoza","D":"Hernán Cortés"}'::jsonb, 'B', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0080', 'Historia', 'México: Conquista y periodo colonial (Virreinato)', 2, null, null, '¿Qué cronista franciscano es reconocido por documentar extensamente la cultura y la lengua náhuatl en obras como el Códice Florentino?', '{"A":"Fray Bernardino de Sahagún","B":"Fray Juan de Zumárraga","C":"Hernán Cortés","D":"Fray Bartolomé de las Casas"}'::jsonb, 'A', 'Concepto fundamental de la historia colonial de México (Virreinato de la Nueva España).'),
  ('HMX-0081', 'Historia', 'México: Independencia de México', 2, null, null, '¿En qué año inició el movimiento de Independencia de México con el Grito de Dolores?', '{"A":"1821","B":"1810","C":"1910","D":"1519"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0082', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién es reconocido como el iniciador del movimiento de Independencia de México, mediante el Grito de Dolores?', '{"A":"Miguel Hidalgo y Costilla","B":"Agustín de Iturbide","C":"Vicente Guerrero","D":"José María Morelos"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0083', 'Historia', 'México: Independencia de México', 2, null, null, '¿En qué año se consumó la Independencia de México?', '{"A":"1821","B":"1836","C":"1810","D":"1824"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0084', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué documento firmado en 1821 estableció las bases para la consumación de la Independencia de México?', '{"A":"El Tratado de Córdoba exclusivamente sin relación con el Plan de Iguala","B":"El Plan de Iguala","C":"El Acta de Independencia exclusivamente","D":"La Constitución de 1824"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0085', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién continuó el movimiento de Independencia tras la muerte de Miguel Hidalgo, redactando además los ''Sentimientos de la Nación''?', '{"A":"José María Morelos y Pavón","B":"Vicente Guerrero","C":"Agustín de Iturbide","D":"Ignacio Allende"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0086', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién fue el líder insurgente que, junto con Agustín de Iturbide, firmó el Plan de Iguala y luego se abrazaron en un episodio histórico conocido como el ''Abrazo de Acatempan''?', '{"A":"Ignacio Allende","B":"Miguel Hidalgo","C":"Vicente Guerrero","D":"José María Morelos"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0087', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién se convirtió en el primer emperador de México tras la consumación de la Independencia?', '{"A":"Agustín de Iturbide","B":"Miguel Hidalgo","C":"Antonio López de Santa Anna","D":"Vicente Guerrero"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0088', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué mujer insurgente es reconocida por avisar a los conspiradores sobre el descubrimiento de la conspiración de Querétaro en 1810?', '{"A":"Leona Vicario","B":"La Malinche","C":"Sor Juana Inés de la Cruz","D":"Josefa Ortiz de Domínguez (''La Corregidora'')"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0089', 'Historia', 'México: Independencia de México', 2, null, null, '¿Cuáles son las ''Tres Garantías'' proclamadas en el Plan de Iguala?', '{"A":"Religión, Independencia y Unión","B":"Libertad, Igualdad y Fraternidad","C":"Paz, Trabajo y Progreso","D":"Tierra, Libertad y Justicia"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0090', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué documento redactado por José María Morelos en 1813 estableció principios como la abolición de la esclavitud y la igualdad de todos los mexicanos?', '{"A":"Los Sentimientos de la Nación","B":"La Constitución de Cádiz","C":"El Plan de Iguala","D":"El Tratado de Córdoba"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0091', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué grupo de conspiradores criollos, entre ellos Miguel Hidalgo e Ignacio Allende, planeó el inicio de la lucha independentista en Querétaro?', '{"A":"La conspiración de Querétaro","B":"La Junta de Zitácuaro","C":"El Congreso de Chilpancingo","D":"El Plan de Iguala"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0092', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué congreso, convocado por Morelos en 1813, proclamó formalmente la independencia de México respecto a España?', '{"A":"El Congreso de Apatzingán exclusivamente","B":"El Congreso de Querétaro","C":"El Congreso de Chilpancingo (Congreso de Anáhuac)","D":"El Congreso Constituyente de 1824"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0093', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué tratado, firmado en 1821 entre Agustín de Iturbide y Juan O''Donojú, reconoció formalmente la independencia de México ante España?', '{"A":"El Tratado de Guadalupe Hidalgo","B":"El Tratado de Córdoba","C":"El Plan de Iguala","D":"El Tratado de La Mesilla"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0094', 'Historia', 'México: Independencia de México', 2, null, null, '¿En qué región de México inició principalmente el movimiento armado de Independencia en 1810?', '{"A":"La región del Istmo de Tehuantepec","B":"El Bajío (Guanajuato y alrededores)","C":"La península de Yucatán","D":"El norte de México (Sonora y Chihuahua)"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0095', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué ocurrió con Miguel Hidalgo tras ser capturado por las fuerzas realistas en 1811?', '{"A":"Fue nombrado gobernador de Nueva España","B":"Se exilió en Europa","C":"Fue perdonado y liberado","D":"Fue fusilado y su cabeza expuesta públicamente como escarmiento"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0096', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué otro insurgente destacado, junto con Hidalgo, participó en la conspiración de Querétaro y en las primeras batallas de la guerra de Independencia?', '{"A":"Vicente Guerrero","B":"Guadalupe Victoria","C":"Ignacio Allende","D":"Agustín de Iturbide"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0097', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién es reconocida como una destacada insurgente que apoyó económicamente y con información al movimiento independentista, siendo perseguida por las autoridades virreinales?', '{"A":"Josefa Ortiz de Domínguez exclusivamente en otro episodio","B":"Sor Juana Inés de la Cruz","C":"Leona Vicario","D":"La Malinche"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0098', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué destacado insurgente afromestizo, conocido como ''El Amo Torres'' o por su liderazgo militar en el Bajío, participó en las primeras etapas de la guerra de Independencia?', '{"A":"José María Morelos (afromestizo, no confundir con Hidalgo)","B":"Ignacio Allende","C":"Agustín de Iturbide","D":"Vicente Guerrero exclusivamente en batallas distintas"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0099', 'Historia', 'México: Independencia de México', 2, null, null, '¿En qué batalla de 1810 las fuerzas insurgentes lideradas por Hidalgo obtuvieron una importante victoria cerca de la Ciudad de México?', '{"A":"La Batalla de Calpulalpan","B":"La Batalla del Monte de las Cruces","C":"La Batalla de Puebla","D":"La Batalla de Chapultepec"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0100', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién fue el primer presidente de México tras la caída del Primer Imperio Mexicano de Iturbide?', '{"A":"Anastasio Bustamante","B":"Vicente Guerrero","C":"Guadalupe Victoria","D":"Antonio López de Santa Anna"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0101', 'Historia', 'México: Independencia de México', 2, null, null, '¿Quién sucedió brevemente a Iturbide y fue el segundo presidente de México, además del primer presidente de origen afromexicano en asumir dicho cargo?', '{"A":"Guadalupe Victoria","B":"Nicolás Bravo","C":"Antonio López de Santa Anna","D":"Vicente Guerrero"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0102', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué forma de gobierno adoptó México en su primera Constitución de 1824, tras la caída del imperio de Iturbide?', '{"A":"Una república centralista exclusivamente desde el inicio","B":"Un protectorado español","C":"Una república federal","D":"Una monarquía constitucional"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0103', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué evento marcó el fin del Primer Imperio Mexicano encabezado por Agustín de Iturbide?', '{"A":"El Plan de Iguala","B":"La Batalla de Puebla","C":"El Plan de Casa Mata (1823), que forzó la abdicación de Iturbide","D":"El Tratado de Córdoba"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0104', 'Historia', 'México: Independencia de México', 2, null, null, '¿En qué año fue fusilado Agustín de Iturbide, tras intentar regresar a México desde su exilio?', '{"A":"1821","B":"1810","C":"1836","D":"1824"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0105', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué destacado insurgente, apodado ''El Padre de la Patria'', es honrado junto con Hidalgo como líder fundamental del movimiento independentista, aunque este título se atribuye mayormente a Hidalgo?', '{"A":"Vicente Guerrero","B":"Miguel Hidalgo y Costilla","C":"José María Morelos","D":"Ignacio Allende"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0106', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué documento, promulgado en 1814 por el Congreso de Chilpancingo, es considerada la primera constitución de un México independiente (aunque no llegó a aplicarse plenamente)?', '{"A":"La Constitución de Apatzingán","B":"La Constitución de 1824","C":"El Plan de Iguala","D":"La Constitución de Cádiz"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0107', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué significaba la frase ''Sentimientos de la Nación'' escrita por Morelos en 1813?', '{"A":"Un tratado con España","B":"Una carta personal sin relevancia política","C":"Un poema dedicado a la Virgen de Guadalupe","D":"Un documento que expresaba los principios e ideales políticos y sociales del movimiento insurgente"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0108', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué imagen religiosa fue utilizada como estandarte por Miguel Hidalgo durante el inicio de la lucha insurgente?', '{"A":"La Virgen del Carmen","B":"La Virgen de Guadalupe","C":"El Sagrado Corazón de Jesús","D":"San Miguel Arcángel"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0109', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué papel jugó la Constitución de Cádiz de 1812, promulgada en España, en el contexto de la lucha independentista novohispana?', '{"A":"Prohibió cualquier tipo de reforma en las colonias","B":"No tuvo ninguna relación con los territorios americanos","C":"Estableció directamente la independencia de México","D":"Introdujo ideas liberales y cierta autonomía que influyeron en el pensamiento político novohispano, aunque fue derogada por Fernando VII"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0110', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué grupo social criollo, temeroso de perder sus privilegios ante posibles reformas liberales españolas, apoyó inicialmente el Plan de Iguala como una forma de independencia conservadora?', '{"A":"Los criollos y sectores conservadores de la Nueva España","B":"Los insurgentes radicales de Morelos exclusivamente","C":"La población indígena exclusivamente","D":"El gobierno de España exclusivamente"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0111', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué insurgente es reconocido por su defensa prolongada del sur de México, incluso tras la muerte de Hidalgo y Morelos, resistiendo hasta la alianza final con Iturbide?', '{"A":"Vicente Guerrero","B":"Leona Vicario","C":"Josefa Ortiz de Domínguez","D":"Ignacio Allende"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0112', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué famosa frase se le atribuye a Vicente Guerrero, reflejando su postura ante la propuesta de amnistía realista a cambio de deponer las armas?', '{"A":"\"Viva el rey\"","B":"\"Sufragio efectivo, no reelección\"","C":"\"Tierra y libertad\"","D":"\"La patria es primero\""}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0113', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué territorio de la Nueva España fue de los últimos en sumarse o rendirse durante el proceso de consumación de la Independencia en 1821?', '{"A":"Algunas plazas fuertes realistas, como Veracruz y Acapulco, resistieron hasta después de 1821","B":"Toda la Nueva España se rindió simultáneamente en 1810","C":"Ningún territorio ofreció resistencia adicional tras el Plan de Iguala","D":"La Ciudad de México resistió hasta 1830"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0114', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué significado histórico tiene el 27 de septiembre de 1821 para México?', '{"A":"Es la fecha de la Batalla de Puebla","B":"Es la fecha del Grito de Dolores","C":"Es la fecha de la promulgación de la Constitución de 1824","D":"Es la fecha en que el Ejército Trigarante, encabezado por Iturbide, entró triunfalmente a la Ciudad de México, consumando la Independencia"}'::jsonb, 'D', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0115', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué papel desempeñó el Ejército Trigarante durante la consumación de la Independencia en 1821?', '{"A":"Fue una fuerza exclusivamente indígena sin participación criolla","B":"Fue la fuerza militar conjunta de insurgentes y realistas, liderada por Iturbide, que garantizó las Tres Garantías del Plan de Iguala","C":"Fue el ejército español que reconquistó México en 1829","D":"Fue el ejército francés durante la intervención de 1862"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0116', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué intento de reconquista española sobre México ocurrió en 1829, siendo repelido por fuerzas mexicanas encabezadas por Antonio López de Santa Anna?', '{"A":"La expedición de reconquista de Isidro Barradas","B":"La intervención francesa de los Pasteles","C":"La intervención tripartita de 1861","D":"La invasión estadounidense de 1846"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0117', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué destacado insurgente y posterior primer presidente afromexicano de América murió sin ver consolidada plenamente la república que ayudó a fundar, siendo ejecutado en 1831 tras ser traicionado?', '{"A":"Vicente Guerrero","B":"Guadalupe Victoria","C":"Ignacio Allende","D":"Miguel Hidalgo"}'::jsonb, 'A', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0118', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué significado tiene la fecha del 16 de septiembre de 1810 en la historia de México?', '{"A":"Marca el inicio de la Revolución Mexicana","B":"Marca el inicio del movimiento de Independencia con el Grito de Dolores encabezado por Miguel Hidalgo","C":"Marca la consumación de la Independencia","D":"Marca la promulgación de la Constitución de 1824"}'::jsonb, 'B', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0119', 'Historia', 'México: Independencia de México', 2, null, null, '¿Qué papel jugó el cura Miguel Hidalgo antes de convertirse en líder insurgente, en términos de su ocupación y ubicación?', '{"A":"Era un comerciante español radicado en Veracruz","B":"Era virrey de la Nueva España","C":"Era párroco del pueblo de Dolores, en el actual estado de Guanajuato","D":"Era un militar de alto rango del ejército realista"}'::jsonb, 'C', 'Concepto fundamental de la Independencia de México.'),
  ('HMX-0120', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Quién es considerado el principal impulsor de las Leyes de Reforma en México?', '{"A":"Antonio López de Santa Anna","B":"Porfirio Díaz","C":"Benito Juárez","D":"Maximiliano de Habsburgo"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0121', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué buscaban principalmente las Leyes de Reforma promovidas por Juárez?', '{"A":"Anexar territorio a Estados Unidos","B":"Fortalecer el poder de la Iglesia católica","C":"Establecer una monarquía hereditaria","D":"Separar a la Iglesia del Estado y reducir el poder económico y político del clero"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0122', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué conflicto armado interno (1858-1861) enfrentó a liberales y conservadores mexicanos, en gran parte por las Leyes de Reforma?', '{"A":"La Guerra de Reforma","B":"La Revolución Mexicana","C":"La Guerra de Independencia","D":"La Guerra de los Pasteles"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0123', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué país europeo intervino militarmente en México entre 1862 y 1867, imponiendo un imperio?', '{"A":"Reino Unido","B":"Francia","C":"Alemania","D":"España"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0124', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Quién fue impuesto como emperador de México durante la intervención francesa?', '{"A":"Porfirio Díaz","B":"Maximiliano de Habsburgo","C":"Agustín de Iturbide","D":"Antonio López de Santa Anna"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0125', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿En qué batalla del 5 de mayo de 1862 el ejército mexicano derrotó al ejército francés en Puebla?', '{"A":"La Batalla de Zacatecas","B":"La Batalla de Chapultepec","C":"La Batalla de Puebla","D":"La Batalla de Churubusco"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0126', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿En qué año fue fusilado Maximiliano de Habsburgo, marcando el fin del Segundo Imperio Mexicano?', '{"A":"1867","B":"1862","C":"1821","D":"1876"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0127', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué territorio perdió México tras la guerra con Estados Unidos (1846-1848)?', '{"A":"Ningún territorio significativo","B":"La península de Yucatán","C":"Más de la mitad de su territorio, incluyendo lo que hoy es California, Texas, Nuevo México y otros estados","D":"El estado de Chiapas"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0128', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué tratado puso fin a la guerra entre México y Estados Unidos en 1848?', '{"A":"El Tratado de La Mesilla","B":"El Plan de Iguala","C":"El Tratado de Córdoba","D":"El Tratado de Guadalupe Hidalgo"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0129', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué territorio adicional vendió México a Estados Unidos en 1853, tras la guerra de 1846-1848?', '{"A":"Texas","B":"Baja California","C":"California","D":"La Mesilla (en el actual sur de Arizona y Nuevo México)"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0130', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Cuántas veces ocupó Antonio López de Santa Anna la presidencia de México, en distintos periodos del siglo XIX?', '{"A":"Nunca ocupó la presidencia","B":"En múltiples ocasiones (comúnmente se citan 11 periodos)","C":"Exactamente dos veces","D":"Solo una vez"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0131', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué conflicto se conoce como la ''Guerra de los Pasteles'', ocurrido entre México y Francia en 1838?', '{"A":"La Guerra de Reforma","B":"Un conflicto bélico motivado por reclamaciones de comerciantes franceses por daños durante disturbios en México","C":"La intervención francesa que impuso a Maximiliano","D":"La guerra por la independencia de Texas"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0132', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué documento constitucional de 1857, de corte liberal, fue una de las causas de la Guerra de Reforma?', '{"A":"La Constitución de 1917","B":"La Constitución de 1857","C":"El Plan de Ayutla exclusivamente","D":"La Constitución de 1824"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0133', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué plan político de 1854 buscó derrocar la dictadura de Santa Anna y dio paso a la etapa liberal conocida como la Reforma?', '{"A":"El Plan de Iguala","B":"El Plan de San Luis","C":"El Plan de Guadalupe","D":"El Plan de Ayutla"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0134', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué territorio se independizó de México en 1836 y posteriormente fue anexado por Estados Unidos, detonando la guerra de 1846?', '{"A":"California","B":"Texas","C":"Nuevo México","D":"Arizona"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0135', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué presidente mexicano liberal, opositor a Santa Anna y precursor de las ideas reformistas, gobernó brevemente antes de la Guerra de Reforma?', '{"A":"Ignacio Comonfort","B":"Porfirio Díaz","C":"Benito Juárez (que gobernó después, durante y tras la guerra)","D":"Sebastián Lerdo de Tejada"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0136', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué destacado militar y político liberal sucedió a Benito Juárez en la presidencia tras su muerte en 1872?', '{"A":"Manuel González","B":"Sebastián Lerdo de Tejada","C":"Porfirio Díaz","D":"Ignacio Comonfort"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0137', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué plan político encabezó Porfirio Díaz en 1876 contra la reelección de Lerdo de Tejada, bajo el lema ''no reelección''?', '{"A":"El Plan de Ayutla","B":"El Plan de San Luis","C":"El Plan de Tuxtepec","D":"El Plan de Iguala"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0138', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué grupo político se opuso a las Leyes de Reforma y defendía los privilegios de la Iglesia católica y el ejército durante el siglo XIX?', '{"A":"Los conservadores","B":"Los liberales","C":"Los insurgentes de 1810","D":"Los zapatistas"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0139', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué grupo político impulsó las Leyes de Reforma y defendía un Estado laico, la libertad de cultos y el debilitamiento del poder eclesiástico?', '{"A":"Los conservadores","B":"Los liberales","C":"Los realistas","D":"Los criollos monárquicos"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0140', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué ley de Reforma, promulgada en 1859, estableció la separación oficial entre la Iglesia y el Estado en México?', '{"A":"El Plan de Iguala","B":"El Tratado de Córdoba","C":"La Ley de Nacionalización de Bienes Eclesiásticos (entre el conjunto de Leyes de Reforma de 1859)","D":"La Constitución de 1824"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0141', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué ley de Reforma promovida por Benito Juárez estableció el registro civil de nacimientos, matrimonios y defunciones, antes bajo control eclesiástico?', '{"A":"La Ley de Desamortización","B":"La Ley Juárez","C":"La Ley del Registro Civil","D":"La Ley Lerdo"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0142', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué ley de Reforma, impulsada por Miguel Lerdo de Tejada, ordenaba la venta de las tierras comunales de la Iglesia y de las comunidades indígenas?', '{"A":"La Ley de Nacionalización","B":"La Ley del Registro Civil","C":"La Ley Lerdo (Ley de Desamortización de Bienes de Manos Muertas)","D":"La Ley Juárez"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0143', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué ley de Reforma, impulsada por Benito Juárez cuando era ministro de Justicia, suprimió los fueros especiales del clero y del ejército?', '{"A":"La Constitución de 1857","B":"La Ley del Registro Civil","C":"La Ley Lerdo","D":"La Ley Juárez"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0144', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿En qué ciudad estableció Benito Juárez su gobierno itinerante durante la intervención francesa, resistiendo al imperio de Maximiliano?', '{"A":"En Guadalajara exclusivamente","B":"En Puebla exclusivamente","C":"En la Ciudad de México, bajo control imperial","D":"En diversas ciudades del norte, incluyendo Paso del Norte (hoy Ciudad Juárez)"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0145', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué frase histórica se le atribuye a Benito Juárez, resumiendo su filosofía sobre el respeto entre naciones y personas?', '{"A":"\"La patria es primero\"","B":"\"Tierra y libertad\"","C":"\"Sufragio efectivo, no reelección\"","D":"\"Entre los individuos, como entre las naciones, el respeto al derecho ajeno es la paz\""}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0146', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué emperatriz, esposa de Maximiliano de Habsburgo, viajó a Europa para pedir apoyo militar y político para el imperio mexicano, sin éxito?', '{"A":"Josefa Ortiz de Domínguez","B":"Eugenia de Montijo","C":"Leona Vicario","D":"Carlota de Bélgica (Carlota Amalia)"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0147', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué países, además de Francia, participaron inicialmente en la intervención tripartita de 1861 para cobrar deudas a México, aunque luego se retiraron?', '{"A":"España y el Reino Unido","B":"Rusia y Austria","C":"Italia y Portugal","D":"Estados Unidos y Alemania"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0148', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué medida tomó el gobierno de Benito Juárez en 1861 que provocó la intervención tripartita europea?', '{"A":"La anexión de territorio de Guatemala","B":"La suspensión temporal del pago de la deuda externa mexicana","C":"La expropiación de todas las propiedades extranjeras","D":"La declaración de guerra a Francia"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0149', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué grupo de mexicanos conservadores apoyó la intervención francesa y el establecimiento del imperio de Maximiliano?', '{"A":"Los liberales seguidores de Juárez","B":"Los conservadores mexicanos, que buscaban restaurar una monarquía y frenar las reformas liberales","C":"Los insurgentes de 1810","D":"Los zapatistas del siglo XX"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0150', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué política, paradójicamente, mantuvo Maximiliano de Habsburgo durante su imperio, a pesar de haber sido impuesto por los conservadores?', '{"A":"Abolió completamente todas las Leyes de Reforma","B":"Devolvió todas las tierras a la Iglesia católica","C":"Restauró la Inquisición","D":"Conservó varias de las Leyes de Reforma liberales, lo que le generó el rechazo de los conservadores que lo habían apoyado"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0151', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿En qué ciudad fue fusilado Maximiliano de Habsburgo en 1867?', '{"A":"Veracruz","B":"Querétaro, en el Cerro de las Campanas","C":"Ciudad de México","D":"Puebla"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0152', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué periodo de la historia de México se conoce como la ''República Restaurada'', tras el triunfo definitivo de los liberales sobre el imperio en 1867?', '{"A":"El Porfiriato","B":"El primer imperio de Iturbide","C":"El periodo colonial","D":"El periodo de 1867 a 1876, bajo los gobiernos de Juárez y Lerdo de Tejada"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0153', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué facción política mexicana buscó, sin éxito duradero, establecer una monarquía como forma de gobierno estable tras la independencia, apoyando después la intervención francesa?', '{"A":"Los federalistas radicales","B":"Los liberales puros","C":"Los insurgentes zapatistas","D":"Los conservadores monárquicos"}'::jsonb, 'D', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0154', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué guerra civil mexicana de mediados del siglo XIX enfrentó al gobierno federal con caudillos regionales, en el contexto de las pugnas entre centralistas y federalistas?', '{"A":"La Revolución Mexicana","B":"La Guerra de Independencia","C":"Las guerras y rebeliones federalistas de las décadas de 1830 y 1840 (previas a la Guerra de Reforma)","D":"La Guerra Cristera"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0155', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué diferencia fundamental existía entre el modelo de gobierno centralista y federalista, debatido intensamente en el México del siglo XIX?', '{"A":"No existía ninguna diferencia real entre ambos modelos","B":"El centralismo concentraba el poder en el gobierno nacional, mientras el federalismo otorgaba mayor autonomía a los estados","C":"El federalismo eliminaba por completo al gobierno nacional","D":"El centralismo solo aplicaba a asuntos militares"}'::jsonb, 'B', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0156', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué famoso decreto de 1836, conocido como las ''Siete Leyes'', transformó a México de una república federal a una centralista?', '{"A":"La Constitución de 1857","B":"El Plan de Ayutla","C":"Las Siete Leyes de 1836","D":"La Constitución de 1824"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0157', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué plan de 1854, encabezado por Juan Álvarez y otros liberales, buscó derrocar al régimen dictatorial de Santa Anna, dando inicio a la era de la Reforma?', '{"A":"El Plan de Iguala","B":"El Plan de San Luis","C":"El Plan de Ayutla","D":"El Plan de Tuxtepec"}'::jsonb, 'C', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0158', 'Historia', 'México: México independiente: Reforma e Intervenciones extranjeras', 2, null, null, '¿Qué título honorífico recibió Antonio López de Santa Anna durante uno de sus periodos como gobernante, reflejando el poder casi absoluto que llegó a ostentar?', '{"A":"Su Alteza Serenísima","B":"El Benemérito de las Américas","C":"El Libertador","D":"El Padre de la Patria"}'::jsonb, 'A', 'Concepto fundamental del México independiente del siglo XIX (Reforma e Intervenciones).'),
  ('HMX-0159', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Cuántos años gobernó aproximadamente Porfirio Díaz México, en el periodo conocido como el Porfiriato?', '{"A":"Alrededor de 30 años (con una breve interrupción)","B":"50 años","C":"10 años","D":"5 años"}'::jsonb, 'A', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0160', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué caracterizó económicamente al Porfiriato?', '{"A":"El aislamiento total de México del comercio internacional","B":"Un notable desarrollo de infraestructura (ferrocarriles) y modernización, pero con gran desigualdad social","C":"Una economía completamente igualitaria sin desigualdad social","D":"La abolición completa de la propiedad privada"}'::jsonb, 'B', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
