  ('HMX-0162', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Quién convocó al pueblo mexicano a las armas contra Porfirio Díaz mediante el Plan de San Luis?', '{"A":"Emiliano Zapata","B":"Francisco I. Madero","C":"Venustiano Carranza","D":"Pancho Villa"}'::jsonb, 'B', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
