  ('HMX-0165', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué líder revolucionario del norte de México es conocido por su Ejército Constitucionalista del norte y su relevancia en la lucha contra Victoriano Huerta?', '{"A":"Emiliano Zapata","B":"Maximiliano de Habsburgo","C":"Francisco (Pancho) Villa (aunque Villa lideró la División del Norte, no el Ejército Constitucionalista)","D":"Porfirio Díaz"}'::jsonb, 'C', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0166', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Quién usurpó la presidencia tras el asesinato de Francisco I. Madero en 1913, en un episodio conocido como la ''Decena Trágica''?', '{"A":"Álvaro Obregón","B":"Victoriano Huerta","C":"Plutarco Elías Calles","D":"Venustiano Carranza"}'::jsonb, 'B', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0167', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué líder revolucionario encabezó el movimiento constitucionalista contra Victoriano Huerta y posteriormente se convirtió en presidente?', '{"A":"Emiliano Zapata","B":"Francisco I. Madero","C":"Venustiano Carranza","D":"Pancho Villa"}'::jsonb, 'C', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0168', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿En qué año se promulgó la Constitución Política que rige (con reformas) hasta la actualidad en México, producto de la Revolución?', '{"A":"1821","B":"1857","C":"1910","D":"1917"}'::jsonb, 'D', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
