  ('HMX-0173', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué revolucionario del norte fue asesinado en 1923, tras haber liderado la famosa División del Norte?', '{"A":"Emiliano Zapata","B":"Álvaro Obregón","C":"Venustiano Carranza","D":"Francisco (Pancho) Villa"}'::jsonb, 'D', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0174', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Cómo murió Venustiano Carranza en 1920?', '{"A":"Fue exiliado y murió en España","B":"Fue fusilado en Querétaro","C":"Fue asesinado en Tlaxcalantongo, Puebla, tras huir de la capital ante el levantamiento de Agua Prieta","D":"Murió de causas naturales en la presidencia"}'::jsonb, 'C', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
