  ('HMX-0178', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué conflicto armado (1926-1929) enfrentó al gobierno mexicano con grupos católicos que se oponían a las leyes anticlericales?', '{"A":"La Guerra de Reforma","B":"La Guerra Cristera","C":"La Revolución Mexicana","D":"La Decena Trágica"}'::jsonb, 'B', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0179', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué episodio de 1913, en el que Francisco I. Madero fue derrocado y posteriormente asesinado, es conocido como la ''Decena Trágica''?', '{"A":"Diez días de combates en la Ciudad de México que culminaron con el golpe de Estado de Victoriano Huerta","B":"El inicio de la Guerra Cristera","C":"La firma del Plan de Guadalupe","D":"La batalla final de la Revolución en 1920"}'::jsonb, 'A', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
  ('HMX-0180', 'Historia', 'México: Porfiriato y Revolución Mexicana', 2, null, null, '¿Qué plan, encabezado por Venustiano Carranza en 1913, desconoció el gobierno usurpador de Victoriano Huerta y dio origen al movimiento constitucionalista?', '{"A":"El Plan de San Luis","B":"El Plan de Guadalupe","C":"El Plan de Ayala","D":"El Plan de Agua Prieta"}'::jsonb, 'B', 'Concepto fundamental del Porfiriato y la Revolución Mexicana.'),
